use std::path::Path;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use server::runtime::{Config, ManualClock};

/// 2026-11-09T00:00:00Z, where test clocks start.
pub fn test_epoch() -> SystemTime {
    UNIX_EPOCH + Duration::from_secs(1_794_182_400)
}

/// A clock stopped at [`test_epoch`].
pub fn manual_clock() -> ManualClock {
    ManualClock::new(test_epoch())
}

/// Config text for a server whose data lives in `dir`, on a random local port.
pub fn config_text() -> String {
    r#"
server_id = "chat"
admin_username = "akhil"
listen_address = "127.0.0.1:0"
public_address = "relay.example:443"
database_path = "server.sqlite"
key_dir = "keys"
"#
    .to_owned()
}

/// A config whose database and keys live in `dir`, on a random local port.
pub fn config_in(dir: &Path) -> Config {
    config_with(dir, "")
}

/// [`config_in`] plus extra config text (a `[blob_store]` table goes last).
pub fn config_with(dir: &Path, extra: &str) -> Config {
    match Config::from_toml(&format!("{}\n{extra}\n", config_text()), dir) {
        Ok(config) => config,
        Err(error) => panic!("test config is invalid: {error}"),
    }
}

/// Turns a failure into a test panic naming what failed.
pub trait Check<T> {
    /// The value, or a panic with `what` and the error.
    fn check(self, what: &str) -> T;
}

impl<T, E: std::fmt::Debug> Check<T> for Result<T, E> {
    fn check(self, what: &str) -> T {
        match self {
            Ok(value) => value,
            Err(error) => panic!("{what} failed: {error:?}"),
        }
    }
}

impl<T> Check<T> for Option<T> {
    fn check(self, what: &str) -> T {
        match self {
            Some(value) => value,
            None => panic!("{what}: nothing there"),
        }
    }
}

/// The admin (`akhil@chat`) registered from the bootstrap invite, with one
/// authenticated device.
pub async fn bootstrap_admin(
    server: &harness::TestServer,
    conn: &harness::Conn,
) -> (clients::TestUser, clients::TestDevice) {
    let admin = clients::TestUser::new("akhil");
    let mut device = admin.new_device();
    register(conn, &server.bootstrap_code, &admin, &device)
        .await
        .check("Register (bootstrap)");
    device.authenticate(conn).await;
    (admin, device)
}

/// `Devices.Register` for `user`'s first device.
pub async fn register(
    conn: &harness::Conn,
    code: &str,
    user: &clients::TestUser,
    device: &clients::TestDevice,
) -> Result<pb::RegisterResponse, tonic::Status> {
    Ok(conn
        .devices()
        .register(pb::RegisterRequest {
            invite_code: code.to_owned(),
            join_code: String::new(),
            identity_public_key: user.identity_public_key(),
            certificate: Some(device.certificate.clone()),
        })
        .await?
        .into_inner())
}

/// `Devices.Register` for an open-mode signup (no invite): `user`'s chosen
/// username and an optional join code (dev-onboarding: Open registration).
pub async fn register_open(
    conn: &harness::Conn,
    user: &clients::TestUser,
    device: &clients::TestDevice,
    join_code: &str,
) -> Result<pb::RegisterResponse, tonic::Status> {
    Ok(conn
        .devices()
        .register(pb::RegisterRequest {
            invite_code: String::new(),
            join_code: join_code.to_owned(),
            identity_public_key: user.identity_public_key(),
            certificate: Some(device.certificate.clone()),
        })
        .await?
        .into_inner())
}

/// A new invite for `username`, created by the admin's `device`.
pub async fn create_invite(
    conn: &harness::Conn,
    admin_device: &clients::TestDevice,
    username: &str,
) -> pb::CreateInviteResponse {
    conn.admin()
        .create_invite(harness::authed(
            admin_device.token(),
            pb::CreateInviteRequest {
                username: username.to_owned(),
            },
        ))
        .await
        .check("CreateInvite")
        .into_inner()
}

/// A member invited by the admin, registered with one authenticated device.
pub async fn invite_user(
    conn: &harness::Conn,
    admin_device: &clients::TestDevice,
    username: &str,
) -> (clients::TestUser, clients::TestDevice) {
    let invite = create_invite(conn, admin_device, username).await;
    let code = invite.invite.check("invite").code;
    let user = clients::TestUser::new(username);
    let mut device = user.new_device();
    register(conn, &code, &user, &device)
        .await
        .check("Register");
    device.authenticate(conn).await;
    (user, device)
}

/// A device linked to `user` by `identity_device` and authenticated.
pub async fn link_device(
    conn: &harness::Conn,
    user: &clients::TestUser,
    identity_device: &clients::TestDevice,
) -> clients::TestDevice {
    let mut device = user.new_device();
    conn.devices()
        .link_device(harness::authed(
            identity_device.token(),
            pb::LinkDeviceRequest {
                certificate: Some(device.certificate.clone()),
            },
        ))
        .await
        .check("LinkDevice");
    device.authenticate(conn).await;
    device
}

/// `GetServerInfo`'s external sender entry.
pub async fn server_external_sender(conn: &harness::Conn) -> pb::ExternalSender {
    conn.devices()
        .get_server_info(pb::GetServerInfoRequest {})
        .await
        .check("GetServerInfo")
        .into_inner()
        .server_info
        .check("server_info")
        .external_sender
        .check("external_sender")
}
